use filmcraft_project::{Param,ParamValue};use filmcraft_render::{effects::{apply,FxCtx},image::Image};use serde_json::json;
fn main(){let mut cases=vec![];for(w,h)in[(1,7),(7,1),(6,4),(18,10)]{for amount in[-100.,-50.,-0.0001,0.,100.]{for midpoint in[0.,50.,100.]{for roundness in[-100.,0.,100.]{for feather in[0.,50.,100.]{for color in[[0.,0.,0.,1.],[0.25,0.75,0.125,0.]]{let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]][(i+i/w)%5]).collect();let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;[filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[1]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[2]as f32/255.)*a,a]}).collect();let mut out=Image{w,h,px};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="vignette").unwrap().instance();for(n,v)in[("amount",amount),("midpoint",midpoint),("roundness",roundness),("feather",feather)]{e.params.insert(n.into(),Param::new(ParamValue::Float(v)));}e.params.insert("color".into(),Param::new(ParamValue::Color(color)));let cx=FxCtx{t:filmcraft_time::Tick::ZERO,px_scale:1.,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut out,&e,&cx);cases.push(json!({"parameters":{"amount":amount,"midpoint":midpoint,"roundness":roundness,"feather":feather,"color":color},"width":w,"height":h,"rgba":rgba,"scale":1.,"bits":out.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));}}}}}}let mut media=vec![];
{for tick in[0u64,250000,500000]{
let rgba:Vec<u8>=(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12{255}else{32};[v,v,v,if i%16<8&&i/16<12{128}else{0}]}).collect();let mut frames=vec![];
for index in 0..(1000000-tick).div_ceil(100000){let local=(tick+index*100000).min(500000);let t=local as f64/500000.;let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;let v=filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a;[v,v,v,a]}).collect();let mut frame=Image{w:16,h:16,px};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="vignette").unwrap().instance();for(n,a,b)in[("amount",-50.,-100.),("midpoint",50.,75.),("roundness",0.,-100.),("feather",50.,0.)]{e.params.insert(n.into(),Param::new(ParamValue::Float(a+(b-a)*t)));}e.params.insert("color".into(),Param::new(ParamValue::Color([(t*0.25)as f32,(t*0.75)as f32,(t*0.125)as f32,(1.-t)as f32])));
let cx=FxCtx{t:filmcraft_time::Tick(local as i64),px_scale:1.,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut frame,&e,&cx);frames.push(frame.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());}
media.push(json!({"localTick":tick,"rgba":rgba,"bits":frames[0],"frames":frames}));
}}println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media}));}